import{d as p,C as s,o as d,c as g,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十五章","description":"《正易心法》第十五章——八卦不止，天地雷风：文王周公未当指名物象，故八卦以八德统摄万物，凡健皆乾、凡顺皆坤；一身一物便具八卦之理。","frontmatter":{"title":"正易心法·第十五章","description":"《正易心法》第十五章——八卦不止，天地雷风：文王周公未当指名物象，故八卦以八德统摄万物，凡健皆乾、凡顺皆坤；一身一物便具八卦之理。","category":"guide","aliases":["正易心法第十五章","八卦不止天地雷风","凡健皆乾"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-15.md","filePath":"yijing/zheng-yi-xin-fa/chapter-15.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-15.md"},x=p({...c,setup(u){const i=[{id:"z15-01",label:"一、一身一物据八卦",showLabel:!0,sentences:[["八卦不止，天地雷风。一身一物，便据八卦。"]],note:["八卦不只是天、地、雷、风（等八种具体事物）；任何一个人、任何一件事物，都可以用八卦来分析。（这一句是本章的总纲，也是方法论部分（第十二至十五章）的收束：**由「八字是结构原则」（第十二章）到「万物皆八卦」（本章）。**）"]},{id:"z15-02",label:"二、未当指名物象",showLabel:!0,sentences:[["八卦，文王",{text:"繇辞",glossary:"yaoci"},"，周公爻辞，皆未当指名其物象，以见八卦不止天、地、雷、风、水、火、山、泽，",{text:"无所不统",glossary:"wusuobutong"},"也。"]],note:["文王的卦辞、周公的爻辞，都没有直接指定具体的物象——这正是为了表明八卦不只是天、地、雷、风、水、火、山、泽，而是无所不能统摄的。（**这是一个极重要但容易忽略的论点**：乾的卦辞「元亨利贞」没说「天」，坤的卦辞没说「地」——这不是疏漏，是**故意留白**。一旦说「乾只是天」，乾就被限制死了。）"]},{id:"z15-03",label:"三、八德统摄万物",showLabel:!0,sentences:[["是故凡天下之所谓健者，皆乾也。顺者，皆坤也。动者，皆震也。入者，皆巽也。陷者，皆坎也。丽者，皆离也。止者，皆艮也。说者，皆兑也。"]],note:["因此，凡是天下一切具有刚健特质的，都是乾；柔顺的，都是坤；动的，都是震；渗入的，都是巽；陷溺的，都是坎；附丽的，都是离；停止的，都是艮；喜悦散布的，都是兑。（八德统摄：**天只是「健」的最典型代表，雷只是「动」的最典型代表**——以此类推。这正是第十二章「八字是结构原则」的全面落实：不是「乾＝天」，而是「凡健皆乾」。）"]},{id:"z15-04",label:"四、一身一物便具",showLabel:!0,sentences:[["一身一物，便具此八卦之理。"]],note:["任何一个人、任何一件事物，都具备这八卦的道理。（注意这里的**内外之别**：不是说「八卦可以解释万物」（这还是外在的工具论），而是说「**万物本来就具备八卦之理**」（这是内在的结构论）。这与第五章「合为自然」完全呼应：八卦不是人发明的分析工具，而是万物本来的结构，圣人只是「识取自然」。）"]},{id:"z15-05",label:"五、宣父止以八物",showLabel:!0,sentences:[["然",{text:"宣父",glossary:"xuanfu"},"止以八物云者，特举其大者为",{text:"宗本",glossary:"zongben"},"，姑以入《易》，以便学者耳。"]],note:["然而孔子只用八种具体事物来说，是特别举出最典型的作为根本纲领，姑且用来引导学者入门、方便学者理解罢了。（**这是全书对孔子最温和也最精准的一个评价**：八物不是错误的，而是「入门级」的。就像学数学：小学用具体数字（1+1=2），中学用抽象符号（a+b=c），大学用普遍原则。**孔子的八物是台阶——台阶是用来走上去的，不是用来站在上面不动的。**「宣父」是唐代追谥孔子的尊称。）"]}],o=[{id:"yaoci",term:"繇辞",pinyin:"yáo cí",meaning:"繇通「爻」，此处指文王所作的卦辞。"},{id:"wusuobutong",term:"无所不统",pinyin:"wú suǒ bù tǒng",meaning:"没有什么不能统摄。八卦的义理可以统摄万事万物。"},{id:"xuanfu",term:"宣父",pinyin:"xuān fǔ",meaning:"孔子的尊称。唐代追谥孔子为「宣父」。"},{id:"zongben",term:"宗本",pinyin:"zōng běn",meaning:"根本、纲领。孔子举八物是作为入门的总纲。"}];return(b,n)=>{const l=s("DaoTextReading"),r=s("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第十五章" tabindex="-1">正易心法·第十五章 <a class="header-anchor" href="#正易心法·第十五章" aria-label="Permalink to &quot;正易心法·第十五章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是<strong>方法论部分的总结章</strong>，核心命题分两层：</p><p><strong>第一层（解放）：八卦不被八种物象限制</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文王、周公写卦辞爻辞，故意不直接指定物象</span></span>
<span class="line"><span>——这不是疏漏，而是深意：留白，让八卦保持无限的统摄力</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一旦说「乾只是天」，乾就被限制死了</span></span>
<span class="line"><span>说「凡健皆乾」，乾就可以统摄一切刚健之物</span></span></code></pre></div><p><strong>第二层（落实）：一身一物便具八卦</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不是说「八卦可以解释万物」（外在的工具论）</span></span>
<span class="line"><span>而是说「万物本来就具备八卦之理」（内在的结构论）</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>文王周公「未当指名物象」的深意</strong>——这是本章一个非常重要但容易忽略的论点：</p><table tabindex="0"><thead><tr><th>卦</th><th>卦辞</th><th>有说物象吗</th></tr></thead><tbody><tr><td>乾</td><td>「元亨利贞」</td><td>没有说「天」</td></tr><tr><td>坤</td><td>「元亨，利牝马之贞」</td><td>没有直接说「地」</td></tr><tr><td>坎</td><td>「习坎，有孚，维心亨」</td><td>没有直接说「水」</td></tr></tbody></table><p><strong>麻衣的解释</strong>：文王周公故意不指名物象 = <strong>故意保持开放性</strong> = 让读者从卦画结构理解，而不是从物象对应理解。</p><p><strong>「宗本」与「入门」的教学论</strong>——麻衣对孔子的评价，体现了一种精妙的教学观：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>孔子的八物对应：不是错误的，而是「入门级」的，是「以便学者」的方便法门</span></span>
<span class="line"><span></span></span>
<span class="line"><span>小学：1+1=2（具体数字）</span></span>
<span class="line"><span>中学：a+b=c（抽象符号）</span></span>
<span class="line"><span>大学：∀x∈R（普遍原则）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>孔子的八物 = 小学阶段</span></span>
<span class="line"><span>麻衣的八德 = 中学阶段</span></span>
<span class="line"><span>一身一物便具八卦 = 大学阶段</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣不是批评孔子，而是说：孔子的八物是入门台阶</span></span>
<span class="line"><span>台阶是用来走上去的，不是用来站在上面不动的</span></span></code></pre></div><p><strong>与第四章的深度呼应</strong>：</p><table tabindex="0"><thead><tr><th>章</th><th>性质</th><th>内容</th></tr></thead><tbody><tr><td>第四章</td><td><strong>破</strong>（批评）</td><td>只用八字（物象）理解八卦，是「大略」</td></tr><tr><td>第十五章</td><td><strong>立</strong>（建立）</td><td>八卦统摄万物，一身一物便具八卦</td></tr></tbody></table><p><strong>两章合读，是全书从「破」到「立」的一个完整循环。</strong></p><p><strong>与《说卦传》的方向差异</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《说卦传》：越说越具体——乾为天、为圜、为君、为父、为玉、为金、为寒、为冰、为大赤……</span></span>
<span class="line"><span>麻衣：越说越抽象——只说一个字：健。凡健皆乾，不需要列举</span></span>
<span class="line"><span></span></span>
<span class="line"><span>《说卦传》：乾 = {天, 圜, 君, 父, 玉, 金, 寒, 冰……}（有限集合）</span></span>
<span class="line"><span>麻衣：乾 = 健（无限开放）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>有限集合永远不够用（总有没列到的）</span></span>
<span class="line"><span>无限开放的原则可以统摄一切</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读「未当指名物象」——<strong>这是本章最好的一步棋</strong>；</li><li>再看八德统摄（「凡健皆乾」那一串）；</li><li>最后读对孔子的评价——<strong>注意麻衣批评的从来不是孔子，是「停在台阶上」的人。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>八卦不止八物</strong>：八卦不被天地雷风等限制。</li><li><strong>未指物象</strong>：文王周公故意留白。</li><li><strong>八德统摄</strong>：凡健皆乾，凡顺皆坤……</li><li><strong>一身一物</strong>：万物本具八卦之理（内在，非外在）。</li><li><strong>宣父八物</strong>：孔子的八物是入门的宗本，不是全部。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,23)),e(l,{colophon:"八卦不止 · 未指物象 · 凡健皆乾 · 一身一物",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十五章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（「繇辞」「宣父」皆随底本），不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"未当指名物象",pinyin:["wèi","zhǐ"],meaning:"文王卦辞、周公爻辞都没有直接指定物象——不是疏漏，是故意留白，保持八卦无限的统摄力。"},{term:"凡健皆乾",pinyin:["fán","jiàn"],meaning:"八德统摄：凡天下一切刚健的皆是乾，柔顺的皆是坤……天只是「健」的最典型代表。"},{term:"一身一物",pinyin:["yī","shēn"],meaning:"不是说「八卦可以解释万物」（外在工具论），而是说「万物本来就具备八卦之理」（内在结构论）。"},{term:"宗本",pinyin:["zōng","běn"],meaning:"根本、纲领。孔子举八物是作为入门的总纲，「以便学者」——台阶是用来走上去的。"},{term:"宣父",pinyin:["xuān","fǔ"],meaning:"孔子的尊称。麻衣评孔子止以八物言之，只是「特举其大者为宗本」，非批评孔子。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>方法论部分的总结章</strong>，核心命题两层：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解放：八卦不被八种物象限制（文王周公故意不指名物象）</span></span>
<span class="line"><span>落实：一身一物便具八卦（万物本具八卦之理，非外在工具）</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>文王周公「未当指名物象」的深意</strong>：乾的卦辞「元亨利贞」没说「天」；坤卦辞没说「地」——<strong>这不是疏漏，是故意留白。</strong> 一旦说「乾只是天」，乾就被限制死了；说「凡健皆乾」，乾就可统摄一切刚健之物。</p><p><strong>「宗本」与「入门」的教学论</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>孔子的八物 = 小学阶段（具体对应）</span></span>
<span class="line"><span>麻衣的八德 = 中学阶段（结构原则）</span></span>
<span class="line"><span>一身一物便具八卦 = 大学阶段（万物皆易）</span></span></code></pre></div><p><strong>麻衣不是批评孔子，而是说：孔子的八物是入门台阶——台阶是用来走上去的，不是用来站在上面不动的。</strong></p><p><strong>与第四章的呼应</strong>：</p><table tabindex="0"><thead><tr><th>章</th><th>性质</th><th>内容</th></tr></thead><tbody><tr><td>第四章</td><td>破</td><td>只用八字（物象）理解八卦，是「大略」</td></tr><tr><td>第十五章</td><td>立</td><td>八卦统摄万物，一身一物便具八卦</td></tr></tbody></table><p><strong>两章合读，是全书从「破」到「立」的完整循环。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li><strong>练习一（承接昇哥的钩子）</strong>：用八卦分析一件熟悉的事物——<strong>一本书</strong>：哪个部分是乾（健，主干、立场）、坤（顺，装帧、承载）、震（动，开篇的动力）、巽（入，字句的渗透）、坎（陷，最难的章节）、离（丽，最亮的部分）、艮（止，结论的收束）、兑（说，与人分享的乐趣）？<strong>不需要标准答案——能自圆其说，就说明掌握了麻衣的方法。</strong></li><li><strong>练习二</strong>：分析自己手边正在做的一件事，看它在八德上分别落在哪里；</li><li>记住一句自问：<strong>我是在收集「什么等于什么」的对应表，还是在理解「凡……皆……」的原则？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>八卦不只是天、地、雷、风（等八种具体事物）；任何一个人、任何一件事物，都可以用八卦来分析。</p><p>文王的卦辞、周公的爻辞，都没有直接指定具体的物象——这正是为了表明八卦不只是天、地、雷、风、水、火、山、泽，而是无所不能统摄的。</p><p>因此，凡是天下一切具有刚健特质的，都是乾；柔顺的，都是坤；动的，都是震；渗入的，都是巽；陷溺的，都是坎；附丽的，都是离；停止的，都是艮；喜悦散布的，都是兑。</p><p>任何一个人、任何一件事物，都具备这八卦的道理。</p><p>然而孔子只用八种具体事物来说，是特别举出最典型的作为根本纲领，姑且用来引导学者入门、方便学者理解罢了。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第十五章把八卦从「八个物象」彻底解放成「八种德性」——<strong>从此《易》不再是关于天地的书，是关于一切的书。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「未当指名物象」</strong>——这是本章最好的一步棋。<strong>文王周公不是不知道乾是天，是不说。</strong> 这个「不说」，就是给后人的空间。<strong>好的文本都留白；留白不是省略，是尊重。</strong></li><li><strong>「凡健皆乾」</strong>——一句话把《易》的适用范围放开了。<strong>从「乾＝天」到「凡健皆乾」，是《易》从占卜工具变成思维方式的那一步。</strong></li><li><strong>「一身一物，便具此八卦之理」</strong>——<strong>内与外</strong>的分野：不是我拿八卦去分析万物，是万物本来就是这样。<strong>这就像「万有引力不是牛顿发明的」。</strong></li><li><strong>「宣父止以八物」</strong>——麻衣批评的从来不是孔子，是停在台阶上的人。<strong>这一句很温柔，也很扎心：我是不是也常常把入门工具当成终点？</strong></li><li><strong>练习</strong>（昇哥留的钩子）：用一本书做一次八卦分析——<strong>哪个部分是健、顺、动、入、陷、丽、止、说？</strong> 我的想法：<strong>书的主旨与立场是乾（健），装帧与篇幅是坤（顺），开篇的动因是震（动），行文的渗透力是巽（入），最难的章节是坎（陷），最精彩的部分是离（丽），结论收束是艮（止），与人分享的愉悦是兑（说）。</strong> 不需要标准答案——<strong>能自圆其说，就是学会了。</strong></li><li><strong>与第十五章一起收束的方法论</strong>：第十二章「八字是结构原则」、第十三章「坎兑二水」、第十四章「坎离日月」、第十五章「万物皆八卦」——<strong>四章走完，方法论部分就完成了。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-04">第四章 · 《易》道不传</a> — 「只作八字说」之弊（本章是完整的正面建立）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-05">第五章 · 无穷妙义</a> — 「合为自然」：万物本具八卦之理</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-12">第十二章 · 八字非标签</a> — 八字是结构原则（本章是其总应用）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-13">第十三章 · 坎兑二水</a> — 具体应用一</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-14">第十四章 · 人之坎离</a> — 具体应用二</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 八卦物象的详尽列举（本章说那只是宗本，非全部）</li></ul>`,26))])}}});export{y as __pageData,x as default};
